@cuda.jit(device=True, forceinline=True)
def _batch1024_panel_update_solve_body(
    factor,
    factor_half,
    output,
    panel_col_base,
    panel_row_base,
    current_tile,
    shared,
):
    group = cuda.blockIdx.x
    sample = cuda.blockIdx.y
    factor_base = (
        sample * _D256_MATRIX_ELEMENTS
    )
    factor_half_base = (
        sample * _B1024_FACTOR_SIDECAR_TILES * _D256_TILE_ELEMENTS
    )
    output_base = sample * 1024 * 1024
    panel_row_origin = panel_row_base + group * _D256_NB
    accumulator = shared[0:_B1024_FP32_TILE_ELEMENTS]
    workspace = shared[
        _B1024_FP32_TILE_ELEMENTS :
        _B1024_FP32_TILE_ELEMENTS + _B1024_HALF_TILE_ELEMENTS
    ]
    update_shared = workspace.view(np.float16)
    update_factor_shared = update_shared[0:_B1024_HALF_TILE_ELEMENTS]
    update_panel_shared = update_shared[
        _B1024_HALF_TILE_ELEMENTS : 2 * _B1024_HALF_TILE_ELEMENTS
    ]

    # Stage the FP32 accumulator with the producer warps while all threads
    # convert the first LD72 factor/panel pair.  Subsequent rank-k terms reuse
    # the same compact half workspace, so no triangular-solve fragments remain
    # live in this kernel.
    _b1024_panel_async_load(
        output,
        output_base
        + panel_row_origin * 1024
        + panel_col_base
        + current_tile * _D256_NB,
        1024,
        accumulator,
    )
    _b1024_panel_load_update(
        factor_half,
        output,
        factor_half_base,
        output_base,
        0,
        current_tile,
        panel_col_base,
        panel_row_origin,
        update_factor_shared,
        update_panel_shared,
    )
    _b1024_panel_async_wait()
    _b1024_panel_gemm.execute(
        -1.0,
        update_factor_shared,
        update_panel_shared,
        1.0,
        accumulator,
    )
    cuda.syncthreads()
    for previous_tile in range(1, current_tile):
        _b1024_panel_load_update(
            factor_half,
            output,
            factor_half_base,
            output_base,
            previous_tile,
            current_tile,
            panel_col_base,
            panel_row_origin,
            update_factor_shared,
            update_panel_shared,
        )
        _b1024_panel_gemm.execute(
            -1.0,
            update_factor_shared,
            update_panel_shared,
            1.0,
            accumulator,
        )
        cuda.syncthreads()
    solve_factor_shared = shared[
        _B1024_FP32_TILE_ELEMENTS : 2 * _B1024_FP32_TILE_ELEMENTS
    ]
    _b1024_panel_load_factor_tile(
        factor,
        factor_base,
        current_tile,
        current_tile,
        solve_factor_shared,
    )
    _b1024_panel_apply_solve_bank(solve_factor_shared, accumulator)
    _b1024_panel_store(
        accumulator,
        output,
        output_base,
        panel_row_origin,
        panel_col_base + current_tile * _D256_NB,
    )


