void batch_lower_copy_cuda(torch::Tensor input, torch::Tensor output) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(
        input.scalar_type() == torch::kFloat32
        && output.scalar_type() == torch::kFloat32,
        "FP32 tensors required"
    );
    TORCH_CHECK(
        input.dim() == 3 && input.size(1) == input.size(2)
        && input.is_contiguous() && output.is_contiguous()
        && input.sizes() == output.sizes(),
        "matching contiguous batched square matrices required"
    );
    const int n = static_cast<int>(input.size(1));
    const int batch = static_cast<int>(input.size(0));
    TORCH_CHECK((n & 3) == 0, "matrix width must be float4 aligned");
    const int rows = batch * n;
    const int row_groups = (rows + 7) / 8;
    // NCU measured six resident blocks per SM and a partial-wave tail on B200.
    const int blocks = row_groups < 888 ? row_groups : 888;
    batch_lower_copy_kernel<<<
        blocks, 256, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()
    >>>(
        input.data_ptr<float>(), output.data_ptr<float>(), n, batch
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

