__global__ void gather_batch_factor_and_pointers_kernel(
    const float* __restrict__ diagonal,
    float* __restrict__ factor,
    int64_t* __restrict__ pointers,
    int size,
    int batch,
    long long diagonal_stride,
    long long diagonal_row_stride,
    long long factor_stride,
    long long factor_row_stride,
    long long factor_col_stride
) {
    int tile_col = static_cast<int>(blockIdx.x);
    int tile_row = 0;
    while (tile_col > tile_row) {
        tile_col -= tile_row + 1;
        ++tile_row;
    }
    __shared__ float tile[32][33];
    const int batch_index = static_cast<int>(blockIdx.z);
    const int source_row_base = tile_row * 32;
    const int source_col = tile_col * 32 + threadIdx.x;
    for (int offset = 0; offset < 32; offset += 8) {
        const int source_row = source_row_base + threadIdx.y + offset;
        if (source_row < size && source_col < size
            && source_row >= source_col) {
            tile[threadIdx.y + offset][threadIdx.x] = diagonal[
                static_cast<long long>(batch_index) * diagonal_stride
                + static_cast<long long>(source_row) * diagonal_row_stride
                + source_col
            ];
        }
    }
    __syncthreads();

    const int factor_row = source_row_base + threadIdx.x;
